const { execFile, execFileSync } = require('child_process')
const options = { encoding: 'utf8', windowsHide: true, timeout: 120000, killSignal: 'SIGKILL', maxBuffer: 1024 * 1024 }

module.exports = function command (binary, env, failure) {
  return {
    get (args) {
      return new Promise((resolve, reject) => {
        const child = execFile(binary, args, { ...options, env }, (error, stdout) => {
          // Never expose subprocess errors or output, which may contain secrets.
          if (error) reject(failure())
          else resolve(stdout.trim())
        })
        if (child.stdin) {
          child.stdin.on('error', () => {})
          child.stdin.end()
        }
      })
    },
    getSync (args) {
      try { return execFileSync(binary, args, { ...options, env, stdio: ['ignore', 'pipe', 'pipe'] }).trim() } catch { throw failure() }
    }
  }
}
